function instanciarEstadoInicial(){
  const keys=['clientes','processos','documentos','compromissos','lancamentos','tarefas','colaboradores','intimacoes'];
  keys.forEach(k=>{ if(!estado[k]||!Array.isArray(estado[k])){ estado[k]=JSON.parse(JSON.stringify(MODELO_SEED[k])); } });
  // garante ids em itens de semente que estejam sem eles
  const garantidores={clientes:'c',processos:'p',documentos:'d',compromissos:'co',lancamentos:'la',tarefas:'tk',colaboradores:'cm',intimacoes:'in'};
  for(const k of Object.keys(garantidores)){
    const arr=estado[k];
    arr.forEach(it=>{ if(!it.id){ const cop=Object.assign({},it); cop.id=garantidores[k]+'-'+generateHex(5); estado[k]= [...arr].indexOf(it)>=0? cop : cop; }});
    // corrigir referência cruzada simples (ids novos precisam ser únicos): re-varrer após
  }
  // Deduplicação básica de ids gerados
  const uniqObj = arr => { const m={}; return [...arr].filter(x=>{ if(!m[x.id]){m[x.id]=true;return true;}return false;});};
  estado = uniqObj(estado.clientes).map(c=>{const i=uniqObj(estado.clientes).indexOf(c); return {...c};});
  estado = uniqObj(estado.processos).map(p=>{const i=uniqObj(estado.processos).indexOf(p); return {...p};});
  estado.clientes=uniqObj(estado.clientes);
  estado.compromissos=uniqObj(estado.compromissos);
  estado.lancamentos=uniqObj(estado.lancamentos);
  estado.tarefas=uniqObj(estado.tarefas);
  estado.colaboradores=uniqObj(estado.colaboradores);
}
function gerarHex(n){ let h=Math.floor(Math.random()*16777215); return h.toString(16).padStart(n,'0'); }
/* Estado persistido */
function carregarEstado(){
  try{ const br=localStorage.getItem(APP_KEY); if(br){ const o=JSON.parse(br); if(o){ Object.keys(MODELO_SEED).forEach(k=>{if(!(k in o)) o[k]=MODELO_SEED[k];}); return o; }} }catch(e){}
  instanciarEstadoInicial();
  return {
    clientes:estado.clientes||[],processos:estado.processos||[],documentos:estado.documentos||[],
    compromissos:estado.compromissos||[],lancamentos:estado.lancamentos||[],tarefas:estado.tarefas||[],
    colaboradores:estado.colaboradores||[],intimacoes:estado.intimacoes||[],config:estado.config||{}
  };
}

