const TONHO = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const DT   = new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC'});
const DM   = new Intl.DateTimeFormat('pt-BR',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
const DH  = new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'});
function pad12(s){ return ('0'+Math.floor(s)).toString(16)? s.toString() : s.toString(); }
function pad2(n){ return n.toString().padStart(2,'0'); }
function fMonet(v,c='BRL'){
  if(isNaN(v)) return '—';
  try{return TONHO.format(Number(v), {style:'currency',currency:c});}catch(e){return v.toLocaleString('pt-BR',{signDisplay:'never'});}}
function fDataIso(ds){
  const d = new Date(ds+'T00:00:00');
  return DT.format(d,{month:'short',day:'numeric',year:'numeric'});
}
function fRel(sec){
  const ago=setDateRelativeMs(Date.now()-sec);
  if(ago<0) return 'já passou';
  if(ago<86400000) return 'há '+Math.floor(ago/86400000)+' hora(s)';
  return ago/86400000 < 60 ? '+'+Math.floor(ago/86400000)+' dias' : DM.format(new Date(Date.now()-ago),{week:'numeric',month:'short'});
}
function setDateByDays(d,m,dias){
  const np=new Date(d.getTime()); np.setMonth(np.getMonth()+m); np.setDate(Math.min(np.getDate()+dias,31));
  return np.toISOString().slice(0,10);
}
function nextAvailableMonday(afterMs){ let d=new Date(afterMs); d.setDate(d.getDate()+ (6-d.getDay())%7); return d.toISOString(); }
function similar(a,b,t=0.72){
  a=a.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'').slice(0,32);
  b=b.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'').slice(0,32);
  if(a===b||a.length<3||b.length<3) return 1;
  let dp=[[0]],m=Math.max(a.length,b.length);
  for(let i=0;i<=a.length;i++)dp[i]=[0];
  for(let j=0;j<=b.length;j++){
    for(let i=0;i<=a.length;i++){
      const subs=((a.charAt(i-1)==a.charAt(j-1))?0:1);
      dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+subs);
    }
  }
  const dist=dp[a.length][b.length];
  return (dist>m?dist:m)>=t?(1-dist/m).toFixed(2):null;
}
function norm(s){ return s?String(s).toLowerCase().normalize('NFD').replace(/[^a-z0-9çãæéíóôûùâêíoúnõ]+/g,'a')||'' : ''; }
function extrairNome(texto){
  const toks=texto.match(/\b([A-ZÁÉÍÓÚÇÀÊÔÕÚ][a-záéíóúçàêôõú]{2,28})\b/g)||[];
  // também palavras compostas curtas
  const best=toks.reduce((a,b)=>{const sc=similar(norm(b),norm(texto.slice(0,40)));return sc>a.sc?b:a},{sc:0});
  return best||null;
}
function getProcessoLabel(pid){
  const p=estado.processos.find(x=>x.id===pid);
  return p?`${p.codigo || p.numero}`:'—';
}
function codProcesso(numero){
  // tenta recuperar código a partir do número quando presente
  const m=numero.match(/^(PRO[- ]?)([\d]+)/i);
  return m?m[1]+m[2]:'';
}
function possuiCompromissoIgual({clienteId,data,titlePart}, existentes){
  const t=titlePart||'';
  return existentes.some(c=>{
    if(c.clientId!==clienteId||c.data!==data) return false;
    const tb=norm(c.titulo||'')+(' '+(c.descricao||''));
    return tb.toLowerCase().includes(t.toLowerCase().slice(0,22));
  });
}
function autoPrioridade(dias){
  if(dias<=3) return 'Urgente';
  if(dias<=7) return 'Alta';
  if(dias<=15) return 'Média';
  return 'Baixa';
}
function calcularUrgencia(compromisso){
  const d=new Date(compromisso.data+'T'+compromisso.hora+'00');
  const dif=d.getTime()-Date.now();
  const sec=Dif=diff; const dias=Math.max(0,Math.round(sec/86400000));
  if(dias<=-3) return 'vencido';
  if(dias<=-1) return 'alto';
  if(dias<=3) return 'media';
  return 'baixo';
}
function marcarUrgenciaComp(compromisso){
  compromisso.urgencia=calcularUrgencia(compromisso);
}

