let lastFocus=null, activeRoute=null, activeTabIndex=-1, sortKeys={}, busca={}, destaques={}, timerDestaque=0, animToast=[], focoPrev;

function setup(){
  // evento de busca global
  document.getElementById('busca-global').addEventListener('input', e=>{ const v=e.target.value; setBusca('dashboard',v||null); renderTudo(); });
  document.getElementById('bell-btn').addEventListener('click', ()=>{ document.getElementById('bell-root').scrollIntoView({behavior:'smooth'}); });
  const ul=document.querySelector('.dmenu'); if(!ul) return;
  document.getElementById('user-btn').addEventListener('click', ()=>{
    const root=document.getElementById('user-dropdown-root');
    const exp=root.dataset.exp||'';
    if(exp==='show'){ root.dataset.exp='hide'; ul.classList.remove('show'); lastFocus=root.querySelector('a[data-action="settings"];button[data-action="logout"]');}else{
      root.dataset.exp='show'; ul.classList.add('show');
      const target=root.querySelector('a[data-action="settings"],button[data-action="logout"]');
      target&&target.focus();
    }
  });
  document.querySelectorAll('.nav-item').forEach(el=>{
    el.addEventListener('click',()=>{
      document.querySelectorAll('.nav-item').forEach(i=>i.classList.remove('active'));
      document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));
      const r=el.dataset.rot||el.dataset.action;
      if(r==='logout'){ location.reload(); return; }
      if(r==='settings'){ switchView('config',null); return; }
      activeRoute=r; activateNav(el); activateTab(r); renderTudo();
    });
  });
  document.querySelectorAll('.tab').forEach(t=>{
    t.addEventListener('click', ()=>{
      document.querySelectorAll('.tab').forEach(i=>i.classList.remove('active'));
      const idx=ROTAS.indexOf(t.getAttribute('for'));
      if(idx<0) return;
      activeRoute=ROTAS[idx];
      t.classList.add('active');
      document.querySelectorAll(`.nav-item`).forEach(n=>{ n.classList.toggle('active', ROTAS.indexOf(NAV[ROTAS.indexOf(n).dataset.rot])===idx); });
      activateTab(ROTAS[idx]); renderTudo();
    });
  });
  document.querySelectorAll('.result-list li').forEach(li=>{
    li.addEventListener('click', e=>{ if(e.target.closest('a'))return; const m=li.dataset.mod; setBusca(m, li.dataset.q); renderTudo(); });
  });
  document.querySelectorAll('.task-row').forEach(row=>{
    row.addEventListener('click', ()=>{ const id=row.dataset.toggle; if(id==='bulk'){ toggleBulkTudo(); }else{ toggleTarefa(id); } });
  });
  document.querySelectorAll('.list-item').forEach(itens=>{
    itens.addEventListener('click', ()=>{ itens.closest('.list-wrapper')?.scrollIntoView?.({block:'nearest'}); });
  });
  // modais
  const mc=document.getElementById('modal-card');
  mc.addEventListener('click', e=>{ if(e.target===mc || e.target===document.getElementById('modals')) fecharModal(); });
  document.addEventListener('keydown', e=>{ if(e.key==='Escape'){ fecharModal(); } });
  document.getElementById('modal-cancel').addEventListener('click', fecharModal);
  document.getElementById('modal-confirm').addEventListener('click', ()=>{
    const form=document.activeElement?.closest('form') || document.querySelector('[data-modal-form]');
    if(!form) return;
    const valid = validarFormulario(form);
    if(!valid){ showToast('✗ Corrija os campos destacados.', 'erro'); return; }
    try{ processForm(form); }catch(err){ showToast(String(err),'erro'); }
  });
  // tooltips nativos
  document.querySelectorAll('[title]').forEach(el=>el.setAttribute('data-tip', el.title));
  aplicarTema();
  renderTudo();
  montarGuias();
}

function activateNav(el){ document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active')); el.classList.add('active'); }
function activateTab(rot){ const t=document.querySelector(`[for="${rot}"]`); t?t.classList.add('active'):''; }
function setBusca(rot, val){ busca[rot]=val; renderTudo(); }
function toggleTarefa(id){
  const c=estado.tarefas.find(x=>x.id===id); if(!c) return;
  c.status=c.status==='pendente'?'concluida':'pendente';
  c.data=c.data?new Date(c.data).toISOString().slice(0,10):agoraISO();
  salvar(); marcarTodoComo(); renderTudo();
}
function toggleBulkTudo(){
  const pend=estado.tarefas.filter(t=>t.status==='pendente');
  for(const t of pend){ t.status='concluida'; t.data=agoraISO(); }
  salvar(); renderTudo();
}
function marcarTodoComo(){ const r=document.getElementById('app-tarefas'); if(r){ r.dispatchEvent(new CustomEvent('tarefas-atualizado', {bubbles:true})); } }

/* --------------------------- TOASTS --------------------- */
const TOAST_TYPES={'sucesso':{'icon':'fa-check-circle',cls:'bg-emerald-500/18 border-emerald-500/40 text-emerald-900'},
  'erro':{'icon':'fa-circle-exclamation',cls:'bg-red-500/18 border-red-500/40 text-red-900'},
  'aviso':{'icon':'fa-circle-warning',cls:'bg-yellow-500/18 border-yellow-500/40 text-yellow-900'},
  'info':{'icon':'fa-info-circle',cls:'bg-blue-500/18 border-blue-500/40 text-blue-900'},
  'neutro':{'icon':'fa-circle',cls:'bg-[var(--surface-alt)] border-[var(--border)] text-[var(--text-muted)]'}};
function showToast(msg,tip='info',dur=4200){
  const el=document.createElement('div');
  const t=TOAST_TYPES[tip]||TOAST_TYPES.neutro;
  el.id='toast-'+Date.now();
  el.className=`toast-item ${t.cls}`;
  el.innerHTML=`
    <div class="flex items-center gap-2"><span class="w-8 h-8 flex items-center justify-center"><i class="fa-solid ${t.icon} text-base"></i></span><div class="flex-1 min-w-0"><p class="text-sm leading-snug">${escapeHtml(msg)}</p><small class="text-xs mt-1 opacity-70">${agoraRel()}</small></div></div>
    <button class="w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-bold text-white/90 hover:bg-white/10 transition" aria-label="Fechar aviso" data-delete="${el.id}">✕</button>
  `;
  document.getElementById('toast-container').appendChild(el);
  el.classList.add('animate-toast');
  clearTimeout(el.__timeout__);
  el.__timeout__=setTimeout(()=>{ el.classList.remove('animate-toast'); el.classList.add('anim-toast-out'); },dur);
  el.addEventListener('animationend',()=>{ el.style.transition='opacity .2s'; setTimeout(()=>el.remove(),250); },once:true);
  if(dur>0){ el.__out=setTimeout(()=>{ el.classList.add('anim-toast-out'); },dur-200); }
  animToast.push(el);
  // dedupe mesmo categoria
  const last=document.querySelector(`.${t.cls}:not([style*='visibility:hidden'])`);
  if(last&&!last.dataset._dup){ last.remove(); last=null; }
  if(!last){ el.__dup=false; }
  // dedup ativo
  if(Array.from(el.children[1]?.textContent||'').includes(msg)&&last){ last.remove(); last=null; }
  if(!last) el.style.display='';
}
function agoraRel(){ return fRel(Date.now()-parseInt(new Date().getTime(),'1000'))? fRel(Difference()):'há instantes'; }
function Difference(){ return Date.now()-Date.now(); } // no-op
function agoraRelPreciso(){ return fRel(Math.round(Date.now()-performance.now())); }

/* ===================== FORMULÁRIOS / VALIDAÇÃO ====== */
const RULES={
  nome:{min:2,msg:'Nome inválido.'},
  texto:{min:2,msg:'Campo obrigatório (mínimo 2 caracteres).'},
  email:{reg:/^[^@\s]+@[^@\s]+\.[^@\s]{3,}$/,msg:'E-mail inválido.'},
  cpf:{reg:/^\d{2}\.\d{3}\.\d{3}-\d{2}$/,msg:'Digite o CPF no formato XX.XXX.XXX-XX.'},
  cnpj:{reg:/^\d{2}\.\d{3}\.\d{3}[\/.]?(\d{3})?[\/.]?\d{4}-\d{2}$/,msg:'CNPJ com caracteres inválidos.'},
  tel:{regexp:/^\+?\d{7,14}$/,msg:'Telefone inválido.'},
  valor:{min:0,max:999999999,msg:'Valor inválido.'},
  titDoc:{min:2,msg:'Título obrigatório.'},
  descFin:{min:2,msg:'Descrição obrigatória.'},
  tipoLoc:{msg:'Selecione um tipo.'},
  situacao:{msg:'Selecione uma situação.'},
  dataPrazo:{msg:'Informe a data.'},
  pass:{msg:'Senha insuficiente.'}
};
function mascararCPF(v){
  v=v.replace(/\D/g,''); if(v.length<=3) return v;
  let s=v.substring(0,3)+'.'; s+=v.substring(3,6)+'.'; s+=v.substring(6,9); s+='-'+v.substring(9);
  return s; }
function mascararTel(v){ v=v.replace(/\D/g,''); if(v.length<=2) return v;
  let a=v.substring(0,2); a+=v.substring(2,5); a+=' '; a+=v.substring(5,9); if(v.length>9) a+=v.slice(9);
  return a; }
function validarFormulario(el){
  const corpo=el.querySelector('div[class*="field"]'); corpo&&corpo.forEach(b=>{
    b.classList.remove('error');
    const m=b.getAttribute('name'); if(!m)return;
    const v=b.value.trim();
    const regra=Object.values(RULES).find(r=>r[msg]==m || r.regexp&&m===r.key.toLowerCase());
    const erro=msg||'Valor inválido.';
    if(!v||v.length<2) { b.classList.add('error'); b.parentNode.insertAdjacentHTML('afterbeginning','<span class="field-msg">'+erro+'</span>'); return false; }
    if(regra.regexp&&!regra.regexp.test(v)){ b.classList.add('error'); b.parentNode.insertAdjacentHTML('afterbeginning','<span class="field-msg">'+(regra.msg||erro.replace('Valor inválido.','Formato inválido.'))+'</span>'); return false; }
    if(regra.min && typeof v==='number' && v<regra.min){ b.classList.add('error'); b.parentNode.insertAdjacentHTML('afterbeginning','<span class="field-msg">'+regra.msg+'</span>'); return false; }
    if(regra.regexp&&/\/.*/.test(v) && m==='cnpj'){ /* cnjp */ b.classList.add('error'); b.parentNode.insertAdjacentHTML('afterbeginning','<span class="field-msg">CNPJ mal formatado.</span>'); return false; }
    // limpeza mensagens
    const msgs=b.parentElement.querySelectorAll(':scope > .field-msg'); msgs.forEach(m=>m.remove());
  });
  const erros=document.querySelectorAll('.field-msg'); return erros.length===0;
}
function escapeHtml(s){ return String(s||'')
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }

