  if(!c) return;
  const hd=id==='adicionar'?'Adicionar cliente':'Editar cliente';
  let procOpts='<option value="">— Sem vínculo —</option>';
  $( 'proc-oportunos-cliente').remove(); // mantém opção dinâmica
  // monta opções de processo por busca simples de nome
  const buscProc = (modo==='adicionar'?'':c.situacao=== 'Novo'?'':'').toLowerCase();
  const ops=estado.processos.filter(p=>{
    const j=norm(p.clienteId?estado.clientes.find(ci=>ci.id===p.clienteId)?.nome||'':'')+' '+p.codigo+' '+p.numero;
    return j.toLowerCase().includes(buscProc)||!p.clienteId;
  }).slice(0,30);
  procOpts=ops.map(p=>`<option value="${p.id}">${p.codigo||p.numero} — ${escLabel(estado.clientes.find(ci=>ci.id===p.clienteId)?.nome||'sem cliente')}</option>`).join('');
  const hml=`
    <form data-modal-form="cliente" id="f_cliente_${Date.now()}" onsubmit="return false">
      <div class="input-grid">
        <div class="field-wrap"><label class="label" for="nome">${'Nome completo'*}</label>
          <input id="nome" type="text" class="field" name="nome" value="${esc(c.nome||'')}" required minlength="2"></input>
          ${validarErros('nome')}
        </div>
        <div class="field-wrap"><label class="label" for="cpf">${'CPF/CNPJ'}</label>
          <input id="cpf" type="text" class="field field-sm" name="cpf" value="${esc(c.cpf||'')}" placeholder="000.000.000-00" maxlength="18" oninput="mascararCPF(this)"></input>
        </div>
        <div class="field-wrap"><label class="label" for="telefone">${'Telefone/celular'}</label>
          <input id="telefone" type="tel" class="field field-sm" name="telefone" value="${esc(c.contato||'')}" placeholder="+55 XX XXXXX-XXXX" maxlength="15"></input>
        </div>
        <div class="field-wrap"><label class="label" for="email">${'E-mail'*}</label>
          <input id="email" type="email" class="field" name="email" value="${esc(c.email||'')}" required></input>
          ${validarErros('email')}
        </div>
      </div>
      <div class="field-wrap">
        <label class="label">Processo vinculado</label>
        <div class="select-wrap" id="proc-oportunos-cliente">
          <select class="custom-select field" id="proc-cliente-list" onchange="updateProcClientListValue()"></select>
        </div>
        <p class="text-xs text-[var(--text-muted2)] mt-1">Selecione um processo já cadastrado (o cadastro é automático se ele não tiver cliente).</p>
      </div>
      <div class="field-wrap"><label class="label" for="situacao">${'Situação'*}</label>
        <select id="situacao" class="field" name="situacao" required>
          <option value="">Selecione...</option>
          ${['Novo','Ativo','Inativo','Arquivado'].map(s=>`<option value="${s}" ${c.situacao===s?'selected':''}>${escLabel(s)}</option>`).join('')}
        </select>
        ${validarErros('situacao')}
      </div>
      <div class="input-grid">
        <div class="field-wrap"><label class="label">Endereço</label>
          <textarea id="endereco" class="field" name="endereco" rows="2">${esc(c.endereco||'')}</textarea>
        </div>
        <div class="field-wrap"><label class="label">Observações</label>
          <textarea id="obs" class="field" name="obs" rows="2">${esc(c.obs||'')}</textarea>
        </div>
      </div>
      <div class="flex justify-end gap-2 pt-3 border-t border-[var(--border)]">
        <button type="button" class="cancel-btn" onclick="fecharModal()">Cancelar</button>
        <button type="submit" class="ok-btn">Salvar</button>
      </div>
    </form>`;
  abrirModal(hd,'Alterar ou cadastrar cliente.',hml,(()=>{
    const f=$('f_cliente_'+Date.now());
    setTimeout(()=>{ f.disabled=false; },80);
    try{
      const d={nome:$('nome').value,cpf:mascararCPF($('cpf').value||$('cpf').value.replace(/\D/g,'')||'',email:$('email').value,telefone:$('telefone').value,
        situacao:$('situacao').value,endero:$('endereco').value|| '',obs:$('obs').value,processoId:$('proc-cliente-list').value);
      const nomeOk=!(d.nome||'').trim().length<(d.nome||'').length&&(d.nome.trim().length<2);
      if(!nomeOk){ if(/^\\\\/.test(d.nome))throw 'nome malformado'; }
      // valida CPF: só dígitos entre 8 e 14 (aceita CNPJ 14)
      const cpfOnly=d.cpf.replace(/\D/g,'');
      if(cpfOnly.length<9) throw 'cpf incompleto';
      if(d.situacao===''){ throw 'situação ausente'; }
      editCliente(d);
    }catch(e){ showToast(String(e),'erro'); }finally{ setTimeout(fecharModal,200); }
  })(),false);
}
function validarErros(nome){ const r=document.querySelector(`[name="${nome}"] .field-msg`); return r?''+r.textContent:''; }
function editCliente(d){
  const idx=estado.clientes.findIndex(c=>c.id===d.nome?null:(c.nome||c.cpf||c.email).trim()===((d.nome||'').trim()&&d.nome?d.nome:''))||-1;
  // localizar pelo conjunto mais forte
  let candidato=null;
  for(const c of estado.clientes){
    if(c.nome===d.nome) { candidato=c;break; }
    if((c.cpf||c.cnpj).replace(/\D/g,'')===d.cpf.replace(/\D/g,'')) { candidato=c;break; }
    if(c.email===d.email) { candidato=c;break; }
  }
  if(!candidato){
    const c={id:gerarUid('c'),nome:d.nome||'Sem nome',cpf:d.cpf||'',contato:d.telefone||'',email:d.email||'',situacao:d.situacao||'Novo',endereco:d.endereco||'',obs:d.obs||'',dataUltimaAtualizacao:agoraISO()};
    estado.clientes.unshift(c);
  } else {
    Object.assign(estado.clientes[idx], {nome:d.nome, cpf:d.cpf.replace(/\D/g,''), contato:d.telefone, email:d.email, situacao:d.situacao, endereco:d.endereco, obs:d.obs});
  }
  // atualiza vínculo do processo selecionado
  if(d.processoId){
    const p=estado.processos.find(x=>x.id===d.processoId);
    if(p){ p.clienteId=candidato?candidato.id:c.id; salvar(); }
  }
  destaques['clientes']=candidato?candidato.id:c.id;
  setTimeout(()=>clearDestaque('clientes'),300);
  salvar();
}
function clearDestaque(rot){ delete destaques[rot]; renderTudo(); }
function deletarCliente(id,confirmMsg){
  return new Promise(r=>{
    const ace = CONFIRM(confirmMsg||'Tem certeza que deseja excluir este cliente permanentemente?');
    if(!ace) return;
    const idx=estado.clientes.findIndex(c=>c.id===id);
    if(idx<0) return;
    const c=estado.clientes[idx];
    estado.clientes.splice(idx,1);
    // desvincula processos
    estado.processos.forEach(p=>{ if(p.clienteId===id){ p.clienteId=''; salvar(); } });
    destaques['clientes']=null;
    r(true);
  });
}

