function editProcesso(pd){
  let id=null;
  for(const p of estado.processos){
    if(p.codigop&&p.codigo===pd.codigo){id=p.id;break;}
    if(p.numero===pd.numero){id=p.id;break;}
    if(p.id&&pd.id===id)return; // guarda
    if(p.clienteId===pd.clienteId && pd.vara===p.vara && pd.classe===p.classe) { id=p.id;break; }
  }
  if(!id){
    const pNovo={id:gerarUid('p'),codigo:pd.codigo||'PRO-'+gerarHex(5),numero:pd.numero||'',clienteId:pd.clienteId||null,vara:pd.vara||'',classe:pd.classe||'Cível',status:pd.status||'Em andamento',valorCausa:pd.valorCausa||null,proximaData:pd.proximaData||'',prioridade:pd.prioridade||'Média',dataCriacao:pd.dataCriacao||agoraISO(),obs:pd.obs||''};
    estado.processos.unshift(pNovo);
  } else {
    Object.assign(estado.processos[id], {codigo:pd.codigo, numero:pd.numero, clienteId:pd.clienteId, vara:pd.vara, classe:pd.classe, status:pd.status, valorCausa:pd.valorCausa, proximaData:pd.proximaData, prioridade:pd.prioridade, dataCriacao:pd.dataCriacao||estado.processos[id].dataCriacao, obs:pd.obs});
  }
  // se cliente novo foi criado via select
  if(pd.clienteId){
    const c=estado.clientes.find(x=>x.id===pd.clienteId);
    if(!c){
      const nova={id:gerarUid('c'),nome:'Processo '+pd.codigo||pd.numero+' — cliente a definir',cpf:'',contato:'',email:'',situacao:'Novo',dataUltimaAtualizacao:agoraISO()};
      estado.clientes.unshift(nova);
    }
  }
  destaques['processos']=id;
  setTimeout(()=>clearDestaque('processos'),300);
  salvar(); renderTudo();
}
