/* mini-select de associação de cliente dentro do processo */
function montarMiniSelect(idBox,idProc,callback){
  const box=$id(idBox||('mini-assoquio-'+idProc));
  if(!box) return;
  const trigger=document.createElement('button');
  trigger.className='ms-trigger'; trigger.dataset.actionMenu=`callback:${encodeURIComponent(callback)+'|'+idProc}`;
  trigger.innerHTML='<span class="inline-flex items-center gap-1 text-sm w-full cursor-pointer">'+
    mkIcon('edit','edit','fill')+' '+('Associar / desassociar cliente')+'<svg class="w-3.5 h-3.5 text-[var(--text-muted)]"><path d="M6 6l6 6M6 18l6-6"/></svg>'+'</span>';
  trigger.style.cursor='pointer';
  const wrapper=document.createElement('div');
  wrapper.className='ms-list';
  let aberto=false;
  function abre(){ aberto=!aberto; if(aberto){ wrapper.classList.add('show'); }else{ wrapper.classList.remove('show'); }}
  document.getElementById('modals').addEventListener('pointerdown',e=>{ if(e.target.closest('#modals')||e.target===wrapper) abri(); });
  wrapper.addEventListener('click',e=>{ e.stopPropagation(); abri(); });
  function renderItens(term){
    wrapper.innerHTML='';
    const list=document.createElement('ul');
    const termos=term?term.toLowerCase():'';
    const candidatos=[ ...(estado.clientes.map(c=>({valor:c.id,label:`${escLabel(c.nome)}`}))
      ).filter(x=>!term||norm(x.label).includes(term))
     ];
    if(candidatos.length===0){ list.innerHTML='<li class="px-3 py-2 text-sm text-[var(--text-muted2)]">Nenhum cliente para associar</li>'; }
    else{
      candidatos.slice(0,30).forEach(x=>{
        const li=document.createElement('li');
        li.className='flex items-center justify-between px-3 py-2.5 cursor-pointer rounded-t-md hover:bg-[var(--surface-alt)] transition';
        li.innerHTML=`<span class="text-sm">${escLabel(x.label)}</span><svg class="w-3.5 h-3.5 text-emerald-400 shrink-0"><path d="M4 7l5 5 6-5z"/></svg>`;
        li.addEventListener('click',()=>{ callback(x.valor); abri(); });
        list.appendChild(li);
      });
    }
    wrapper.appendChild(list);
  }
  function aplica(evento){
    const raw=evento.detail||evento.originalEvent?.target?.value||'';
    if(typeof raw==='string'){ try{ callback(raw); }catch(e){} abri(); }
  }
  // bind do mini-select via event listener universal
  wrapper.addEventListener('mouseenter',()=>{ if(!aberto){ abri(); }});
  // captura mudanças programáticas via data-actionMenu
  const parsed=trigger.dataset.actionMenu.split('|');
  const cb=eval(parsed[0])||((v)=>callback(v));
  trigger.addEventListener('click',()=>{ abri(); });
  // registra fechador global
  document.addEventListener('pointerdown',()=>{ if(!aberto) abri(); },false); // não usado assim; manter simples
  trigger.addEventListener('keydown',e=>{ if(e.key==='Escape') abri(); });
  // valor default já vem preenchido no select; ao abrir, aplicar valor atual
  if(wrapper.querySelector('ul li')){
     const sel=$('proc-cliente-list2'); if(sel){ const v=sel.value; const x=estado.clientes.find(c=>c.id===v); if(x) renderItens(''); }
  }
  return trigger;
}
