function renderAgenda(rt){
  const hoje=new Date();
  const base=estado.compromissos.map(c=>({id:c.id,titulo:c.titulo,tipo:c.tipo,data:c.data,hora:c.hora,descricao:c.descricao||'',clienteId:c.clienteId,cliente:estado.clientes.find(x=>x.id===c.clienteId),status:c.status,U:C}),{U:calcularUrgencia});
  // hoje
  const hojeISO=hoje.toISOString().slice(0,10);
  const hojeHoje = base.filter(c=>c.data===hojeISO);
  // faixa 7 dias
  const limite=new Date(hoje.getTime()+7*86400000);
  const proximos=base.filter(c=>{
    const d=new Date(c.data+'T'+c.hora+'00'); return d>hoje.getTime()&&d<=limite.getTime();
  }).sort((a,b)=>a.data+b.hora.localeCompare(b.data+b.hora));
  // atrasados gerais
  const atrasados=base.filter(c=>{
    const d=new Date(c.data+'T'+c.hora+'00'); return d<hoje.getTime();
  }).filter(c=>c.status==='pendente').sort((a,b)=>a.data.localeCompare(b.data));
  const tiposOrdena={ audiencias:'audiencia',prazos:'prazo',telefonos:'phone',documentos:'doc',reunioes:'reuniao' };
  const tipoOrd = {...tiposOrdena,{consulta:'consulta',outros:999},reuniao:'reuniao'};
  const tiposLabel = { audiencia:'AUDIÊNCIA',prazo:'PRAZO',telefon:'TELEFONE',documento:'ENVIO',reuniao:'REUNIÃO',consulta:'CONSULTA',outros:'OUTRO' };
  const filtr = $('filtro-compromissos').value||'';
  let vis=base;
  if(filtr){ vis=base.filter(c=>tiposLabel[c.tipo].toLowerCase().includes(filtr.toLowerCase())); }
  // destaca pendentes não cumpridos
  const pend = vis.filter(c=>c.status==='pendente');
  // organiza para calendário (somente futuros)
  const calendarios=base.filter(c=>{const d=new Date(c.data+'T'+c.hora+'00');return d>=hoje.getTime();}).map(c=>{
    const dt=new Date(c.data+'T'+c.hora+'00');
    const dy=dt.getDate()-hoje.getDate(); const ds=dt.getUTCMonth()-hoje.getUTCMonth();
    const chave=[ds,dy].join('-');
    return {id:c.id, dia:dt.getDate(), mes:dt.getUTCMonth(), ano:dt.getUTCFullYear(), titulo:c.titulo, cor:c.tipo, hora:c.hora, pct:0, urgencia:calcularUrgencia(c), cliente: c.clienteId?estado.clientes.find(x=>x.id===c.clienteId):null, desc:c.descricao||''};
  }).sort((a,b)=>{ if(a.mes!==b.mes)a.mes< b.mes?-1:1;if(a.mes===b.mes)a.dia<b.dia?-1:1;});
  const meses = [new Date(2025,0,1),new Date(2025,5,1),new Date(2025,8,1),new Date(2025,11,1)];
  const mesAtual = Math.max(0, Math.min(3, Math.min(0,Math.floor((new Date().getTime())/86400000)/31-1),3)); // ajustar para janela
