function trocarMes(dir){ const agora=new Date(); const can=[new Date(2025,0,1),new Date(2025,5,1),new Date(2025,8,1),new Date(2025,11,1)];
  let novo=Math.max(0,Math.min(3,agora.getMonth()+dir));
  if(novo>=can.length)novo=can[0].getUTCMonth();
  renderAgenda(null); // re-render usa lógica global de mês
}
