        <button type="button" class="cancel-btn" onclick="fecharModal()">Cancelar</button>
        <button type="submit" class="ok-btn">Adicionar</button>
      </div>
    </form>`;
  abrirModal('Novo compromisso',hml,(()=>{
    const f=$('f_comp_'+Date.now());
    try{
      const tipo=$('ctipo').value;
      const c={
        id:gerarUid('co'),
        titulo:$('ctitulo').value.trim(),
        tipo:tipo,
        data:new Date($('cdata').value+'T00:00:00').toISOString().slice(0,10),
        hora:$('chora').value||'14:00',
        descricao:$('cdesc').value.trim(),
        clienteId:$('ccliente').value||null,
        status:'pendente',
        urgencia:calcularUrgencia({data:'/',hora:'/'}) // placeholder para cálculo imediato abaixo
      };
      // cálculo de urgência real
      const dt=new Date(c.data+'T'+c.hora+'00'); const dif=dt.getTime()-Date.now(); const seg=Math.max(0,Math.floor(dif/86400000));
      if(seg<=-3)c.urgencia='vencido'; else if(seg<=0)c.urgencia='alto'; else if(seg<=3)c.urgencia='media'; else c.urgencia='baixo';
      estado.compromissos.push(c);
      // tarefa automática para prazos/audiências urgentes
      if(['prazo judicial','audiência','consultas e reuniões','reunião'].includes(tipo.toLowerCase())&&seg<=14){
