function criarTarefaAutomatica(comp){
  const tp=comp.tipo.toLowerCase();
  if(!['prazo judicial','audiência','consultas e reuniões','reunião'].includes(tp)) return;
  const dias=parseFloat(comp.hora?Number(comp.data.match(/\d{1,2}/)?.[0]||'5'):5);
  const dur=dias<=3?4:days<=7?8:14;
  const tarefa={id:gerarUid('tk'),titulo:'Follow-up: '+escLabel(comp.titulo),status:'pendente',prioridade:autoPrioridade(dur),responsavel:null,data:new Date().toISOString().slice(0,10),obs:'Criado automaticamente a partir de compromisso. Ref.: '+comp.id};
  estado.tarefas.unshift(tarefa);
}

