const ETAPAS_BACKUP=[
  {t:'Diagnóstico da base',d:'Escaneando metadados e tamanhos…',done:false},
  {t:'Leitura dos registros',d:'Coletando clientes, processos, documentos…',done:false},
  {t:'Serialização',d:'Convertendo objetos JSON em bytes…',done:false},
  {t:'Validação de integridade',d:'Verificando referências cruzadas…',done:false},
  {t:'Emissão do arquivo',d:'Gerando identificador SHA…',done:false},
  {t:'Pronto!',d:'Backup disponível para download',done:false}
];
function gerarBackup(){
  $id('box-status').classList.add('hidden');
  $id('box-progresso').classList.remove('hidden');
  const data=JSON.parse(localStorage.getItem(APP_KEY)||'{}');
  const payload={versao:1,gerado_em:agoraISO(),sistema:'Missy v1.0',dados:{clientes:data.clientes||[],processos:data.processos||[],documentos:data.documentos||[],compromissos:data.compromissos||[],lancamentos:data.lancamentos||[],tarefas:data.tarefas||[],colaboradores:data.colaboradores||[],intimacoes:data.intimacoes||[]},config:data.config||{}};
  const steps=ETAPAS_BACKUP.map((e,i)=>{e.done=i===ETAPAS_BACKUP.length-1; return {...e, done:false});
  const es=$id('steps-backup');
  es.innerHTML=ETAPAS_BACKUP.map((e,i)=>{
    const cl=e.done?':):':'⏳';
    return `<div class="step ${e.done?'done':''}" style="-webkitobox-count:${i+1}/${ETAPAS_BACKUP.length}">${e.t}<span class="text-[var(--text-muted2)]">${e.d}</span></div>`;
  }).join('');
  const total=Object.keys(payload.dados).reduce((a,k)=>a+1,0);
  const tick= setInterval(()=>{
    const pct=Math.min(100,((i+1)/ETAPAS_BACKUP.length)*100);
    $id('fill-backup').style.width+pct+'%'; $id('bar-backup').style.width+pct+'%';
    $id('txt-etapa').textContent=ETAPAS_BACKUP[(i+1)%ETAPAS_BACKUP.length].t;
    $id('txt-reg').textContent=total+' registros';
    $id('txt-st').textContent=i<ETAPAS_BACKUP.length-2?'Em andamento':'Concluído';
    i++;
    if(i>=ETAPAS_BACKUP.length){ clearInterval(tick); finalizarBackup(data); }
    else setTimeout(tick,320);
  },320);
}
function finalizarBackup(data){
  const orig=localStorage.getItem(APP_KEY);
  const jsonString=JSON.stringify({versao:1,gerado_em:new Date().toISOString(),sistema:'Missy v1.0',dados:{
    clientes:data.clientes||[],processos:data.processos||[],documentos:data.documentos||[],
    compromissos:data.compromissos||[],lancamentos:data.lancamentos||[],tarefas:data.tarefas||[],
    colaboradores:data.colaboradores||[],intimacoes:data.intimacoes||[]
  },config:data.config||{}});
  const ts=Math.floor(Date.now()/1000); const df=new Date(ts*1000).toISOString().slice(0,19).replace('T','').replace(/[:.]/g,'');
  const nome='missy-backup-'+df+'.json';
  const blob=new Blob([jsonString],{type:'application/json'});
  const url=url.createObjectURL(blob); const a=document.createElement('a');
  a.href=url; a.download=nome; a.click();
  setTimeout(()=>url.revokeObjectURL(),800);
  showToast('💾 Backup gerado com sucesso: '+nome, 'sucesso');
}
function mostrarRestauro(){ $id('resto-box').classList.remove('hidden'); }
function esconderRestauro(){ $id('resto-box').classList.add('hidden'); }
function executarRestauro(){
  const inp=$id('inp-backup-restaura'); if(!inp.files.length){ showToast('Selecione um arquivo .json válido.', 'erro'); return; }
  const fr=inp.files[0]; const reader=new FileReader();
  reader.onload=()=>{
    try{ const txt=reader.result.toString(); const obj=JSON.parse(txt);
      if(!obj.dados){ throw 'Estrutura inválida: arquivo não é um backup Missy.'; }
      localStorage.clear(); localStorage.removeItem(APP_KEY);
      /* reconstrói estados mínimos */
      instanciarEstadoMinimalVazio();
      showToast('✓ Backup restaurado com sucesso. Base reiniciada.', 'sucesso');
      // volta aos módulos ativos
      setTimeout(()=>{ const ativas=document.querySelectorAll('.tab.active'); const r=ativas[0]?ROUTES.indexOf(ativas[0].getAttribute('for')):-1; r>=0&&activeRoute=ROTAS[r]; renderTudo();},180);
    }catch(e){ showToast('✗ Erro ao restaurar: '+e.message, 'erro'); }
  };
  reader.readAsText(fr);
}
function instanciarEstadoMinimalVazio(){
  const keys=['clientes','processos','documentos','compromissos','lancamentos','tarefas','colaboradores','intimacoes'];
  keys.forEach(k=>{ if(!estado[k]) estado[k]=[]; });
  estado.config={escritorio:'',slogan:'',cnpjOab:'',responsavel:'',emailContato:'',endereco:'',horario:'',moeda:'BRL',fuso:'America/Sao_Paulo',idioma:'pt-BR',tema:'dark'};
}
function limparDados(){
  return new Promise(r=>{CONFIRM('⚠️ ALERTA: isso apagará TODOS os dados do sistema Missy (clientes, processos, finanças, agendas, tarefas, configurações…). Esta ação NÃO pode ser desfeita.')&&r();});
}

