/* Simulador de importação */
function dispararSimulador(){
  const txt=$id('txt-importacao').value.trim().split('\n').map(l=>l.trim()).filter(Boolean).filter(l=>!l.startsWith('#'));
  const clientes=estado.clientes, processos=estado.processos;
  let resultados=[{linha:'Total de linhas analisadas: '+txt.length}, {linha:'Detalhes de parse:',detalhe:''}];
  const criandosClientes=0; const criandosProcs=0; const criandosCompromissos=0; const criadasTarefas=0; const erros=0;
  txt.forEach((linha,i)=>{
    const res=analisarLinha(linha, clientes, processos);
    if(!res) return;
    // evitar duplicar compromisso similar
    if(possuiCompromissoIgual({clienteId:res.cid||null, data:res.dataBase, titulo:res.titulo||''}, estado.compromissos)) return;
    const cid=res.cid;
    let novoCliente=null;
    if(cid){
      if(!clientes.find(c=>c.id===cid)){
        const sug=extrairNome(linha)||'Cliente não identificado';
        if(CONFIRM(`Criar cliente? Sugestão: "${sug}"`)){
          const c={id:gerarUid('c'),nome:sug.trim(),cpf:'',contato:'',email:'',situacao:'Novo',dataUltimaAtualizacao:agoraISO()};
          clientes.unshift(c);
          novoCliente=c;
          resultados.push({linha:`✓ Cliente criado: ${sug} (${c.id.slice(1)})`, detes:'Nova entrada'});
        }
      }
      resultados.push({linha:`Vínculo estabelecido: cliente ${escLabel(clientes.find(x=>x.id===cid)?.nome||cid)}`, detes:'já existia'});
    }
    // processo
    let novoProc=null;
    if(res.pid){
      const p=processos.find(x=>x.id===res.pid);
      if(!p){
        const cl=novoCliente?novoCliente.id:null;
        if(CONFIRM(`Criar processo? Rascunho com base na intimação nº ${i+1}`)){
          const pNovo={id:gerarUid('p'),codigo:'PROC-'+gerarHex(5),numero:`1${pad2(Math.floor(Math.random()*90000)+100000)}.${'2025'}.${'8'}.${'26'}.${pad2(Math.floor(Math.random()*99))}`,clienteId:cl||null,vara:'Vara Cível a definir',classe:'Cível',status:'Em andamento',valorCausa:null,proximaData:setDateByDays(agoraISO(),2),prioridade:'Média',dataCriacao:agoraISO(),obs:linha.slice(0,120)};
          processos.unshift(pNovo);
          novoProc=pNovo;
          resultados.push({linha:`✓ Processo criado: ${pNovo.codigo}`, detes:'novo'});
        }
      }else{
        resultados.push({linha:`Processo vinculado: ${getProcessoLabel(res.pid)}`, detes:'já existia'});
      }
    }
    // compromisso
    const tituloGen = `${res.tipoTexto}${cid?` — ${escLabel(cid?clientes.find(c=>c.id===cid)?.nome||res.alvoMelhor?res.alvoMelhor.nome:'demanda')}`:''}${res.pid?` (${getProcessoLabel(res.pid)})`:''}`.slice(0,70);
    const comp={id:gerarUid('co'),titulo:tituloGen,descricao:linha.slice(0,160),data:res.dataBase,hora:'14:00',tipo:res.tipo,clienteId:cid,status:'pendente',urgencia:res.dataBase?calcularUrgencia({...{data:res.dataBase,hora:'14:00'}}):'baixo'};
    estado.compromissos.push(comp);
    if(res.tipo&&['prazo judicial','audiência','reunião','prazo_pub'].includes(res.tipo)){
      const dur=res.diasDefault||7; const prio=autoPrioridade(res.diasDefault||7);
      const tarefa={id:gerarUid('tk'),titulo:'Follow-up: '+tituloGen.slice(0,60),status:'pendente',prioridade:prio,responsavel:novoCliente?clientes.find(c=>c.id===novoCliente.id)?c.id:null:null,data:comp.data||agoraISO(),obs:'Criado durante importação de intimação.'};
      estado.tarefas.unshift(tarefa);
      criadasTarefas++;
    }
    resultados.push({linha:`✓ Compromisso criado: ${comp.titulo.slice(0,50)} (${fDataIso(comp.data)})`, detes:`tipo ${comp.tipo} · urgência ${comp.urgencia}`});
    // sempre cria tarefa para prazo curto independente? não; só se urgencia alta/media e tipo relevante
  });
  const totalCriados={clientes:criandosClientes,procs:criandosProcs,compromissos:criandosCompromissos,tarefas:criadasTarefas,erros:erros};
  montarResultado(importAreaEl, resultados, totalCriados);
}
function montarResultado(container, itens, resumo){
  let html='';
  if(itens.length===0){ html='<div class="text-center text-[var(--text-muted2)]">Nenhuma intimação válida identificada.</div>'; }
  else{
    html='<div class="text-sm font-semibold mb-2">Resultado da análise:</div>';
    html+=<div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-3">
      ${Object.entries(resumo).map(([k,v)]=>`<div class="text-center rounded-lg p-3 bg-[var(--surface)] border border-[var(--border)]">${k} <div class="text-lg font-bold">${v}</div></div>`).join('')}
    </div>
    html+=itens.map(item=>{
      const dl=item.dete?`<div class="detes">${esc(item.dete)}</div>`:'';
      return `<div class="preview-item" onclick="adiicionarCompromissoDaLinha('${item.linha}')">
        <div class="icon-wrap">${item.dete==='novo cliente'?'<svg class="w-4 h-4 text-emerald-400"><path d="M4 7l5 5 6-5z"/></svg>':'<svg class="w-4 h-4 text-blue-400"><path d="M12 2l7 7-4 4-4-4-4 4 1-3"/><circle cx="12" cy="12" r="8"/></svg>'}${dl}<div class="txt font-medium">${escItemTitulo(item.linha)}</div></div>
        <div class="flex items-center gap-2 text-xs text-[var(--text-muted2)]">
          ${item.dete==='já existia'?'Cliente existente':''}${item.dete==='novo processo'?'Novo processo':'—'} · ${fDataIso(item.dataBase||agoraISO())||''}
        </div>
      </div>`;
    }).join('');
  }
  container.innerHTML=html;
}
function escItemTitulo(linha){
  // tenta achar nome do cliente no texto
  const t=linha;
  const best=extrairNome(t) || t.match(/[A-ZÁÉÍÓÚÇ][a-z]+[a-zA-ZÁÉÍÓÚÇ]*\b\S{0,20}/)?[0]:null;
  return best?best:t.slice(0,55)+'…';
}
function adicionarCompromissoDaLinha(linha){
  // executa parse simples local e cria 1 compromisso manual
  const clientes=estado.clientes, processos=estado.processos;
  const analise=analisarLinha(linha, clientes, processos);
  if(!analise) return showToast('Não foi possível interpretar esta linha.', 'erro');
  const cid=analise.cid;
  let cliente=null;
  if(cid){ cliente=clientes.find(c=>c.id===cid); if(!cliente){
    const sug=extrairNome(linha)||'Cliente não identificado';
    if(!CONFIRM(`Criar cliente "${sug}"?`)){ return; }
    cliente={id:gerarUid('c'),nome:sug.trim(),cpf:'',contato:'',email:'',situacao:'Novo',dataUltimaAtualizacao:agoraISO()}; clientes.unshift(cliente);
  }}
  const comp={id:gerarUid('co'),titulo:`${analise.tipoTexto}${cliente?` — ${escLabel(cliente.nome)}`:''}${analise.pid?` (${getProcessoLabel(analise.pid)})`:''}`,
    descricao:linha.slice(0,150),data:analise.dataBase||setDateByDays(agoraISO(),2),hora:'14:00',
    tipo:analise.tipo||'outros',clienteId:cliente?cliente.id:null,status:'pendente',urgencia:analise.dataBase?calcularUrgencia({...{data:analise.dataBase,hora:'14:00'}}):'media'};
  estado.compromissos.push(comp);
  if(analise.tipo&&['prazo judicial','audiência','reunião'].includes(analise.tipo.toLowerCase())){
    const dur=analise.diasDefault||7; criarTarefaAutomatica({...comp, diasDefault:dur});
  }
  showToast('✓ Intimação processada e compromisso criado.', 'sucesso');
}
