  else{ document.documentElement.classList.remove('theme-claro'); document.body.classList.remove('dark'); }
  document.getElementById('status-tema').textContent=tema==='claro'?'Modo claro':'Modo escuro';
  localStorage.setItem('missy_tempa',tema);
}
